// Devolve ao editor do formulário o recorte com IA feito pelo serviço `declaracao`.
// Nada é guardado: a imagem só passa por esta execução, cujo histórico não é salvo.
const r = $input.first().json;
const ok = r.statusCode === 200 && r.body?.imagem_base64;
const corpo = ok ? r.body : { erro: r.body?.erro ?? 'Não consegui recortar a assinatura com IA. Use o recorte manual.' };
return [{ json: { resposta: JSON.stringify(corpo), content_type: 'application/json; charset=utf-8', status: ok ? 200 : 422 } }];

// Entrada do formulário → campos padronizados e validação do que cada modo exige.
// O Form Trigger 2.1 identifica cada campo pelo rótulo, e o arquivo pelo rótulo com \W → _.
// Estes rótulos precisam ser iguais aos de n8n/montar-workflow.mjs (um teste confere).
const ROTULOS = {
  curso: 'Curso',
  ingresso: 'Ingresso / matriz atual',
  certificado: 'Certificado (PDF)',
  modo: 'Declaração de autenticidade',
  nome: 'Nome completo',
  matricula: 'Matrícula',
  rg: 'RG',
  cpf: 'CPF',
  preparo: 'Preparo da assinatura',
  assinatura: 'Foto da assinatura (JPG ou PNG)',
  declaracao_base: 'Declaração-base (PDF)',
};
const fs = require('fs');
const cursos = JSON.parse(fs.readFileSync('/data/regras/cursos.json', 'utf8'));
const item = $input.first();
const texto = (chave) => (typeof item.json[ROTULOS[chave]] === 'string' ? item.json[ROTULOS[chave]].trim() : '');
const recebidos = item.binary ?? {};
const arquivos = Object.fromEntries(['certificado', 'assinatura', 'declaracao_base']
  .map((chave) => [chave, recebidos[ROTULOS[chave].replace(/\W/g, '_')]])
  .filter(([, arquivo]) => arquivo));

const modo = texto('modo').startsWith('Primeira') ? 'primeiro_uso' : 'reuso';
// As opções de Curso e Ingresso no formulário são os rótulos de regras/cursos.json.
const [cursoId, curso] = Object.entries(cursos).find(([, c]) => c.rotulo_formulario === texto('curso')) ?? [];
const matrizId = curso?.matriz_padrao
  ?? Object.entries(curso?.matrizes ?? {}).find(([, m]) => (
    m.rotulo === texto('ingresso') || (texto('ingresso') && (m.rotulo.startsWith(texto('ingresso')) || texto('ingresso').startsWith(m.rotulo)))
  ))?.[0];
const saida = {
  origem: 'formulario',
  modo,
  versao: 'v2',
  curso: cursoId ?? null,
  matriz: matrizId ?? null,
  nome: texto('nome').replace(/\s+/g, ' '),
  matricula: texto('matricula'),
  rg: texto('rg'),
  // Consentimento explícito: a foto só vai para o Gemini se o aluno escolheu "Com IA".
  assinatura_ia: texto('preparo').startsWith('Com IA'),
  cpf: texto('cpf'),
  erro: '',
};

const faltando = [];
if (!curso) faltando.push('o curso');
else if (!matrizId) faltando.push(`o ingresso (obrigatório para ${curso.nome})`);
if (!arquivos.certificado) faltando.push('o certificado');
if (modo === 'primeiro_uso') {
  if (!saida.nome) faltando.push('o nome completo');
  if (!saida.matricula) faltando.push('a matrícula');
  if (!saida.rg) faltando.push('o RG');
  if (!saida.cpf) faltando.push('o CPF');
  if (!arquivos.assinatura) faltando.push('a foto da assinatura');
  if (!texto('preparo')) faltando.push('a escolha de como preparar a assinatura (com IA ou manual)');
} else if (!arquivos.declaracao_base) {
  faltando.push('a sua declaração-base (PDF que a ferramenta gerou no primeiro uso)');
}

const problemas = [];
if (faltando.length) problemas.push(`Faltou enviar ${faltando.join(', ')}.`);
if (arquivos.certificado && arquivos.certificado.mimeType !== 'application/pdf') {
  problemas.push('O certificado precisa estar em PDF.');
}
if (modo === 'reuso' && arquivos.declaracao_base && arquivos.declaracao_base.mimeType !== 'application/pdf') {
  problemas.push('A declaração-base precisa estar em PDF.');
}
if (modo === 'primeiro_uso') {
  if (arquivos.assinatura && !/^image\/(png|jpe?g)$/.test(arquivos.assinatura.mimeType)) {
    problemas.push('A assinatura precisa ser uma foto em JPG ou PNG.');
  }
  if (saida.matricula && !/^\d{6,15}$/.test(saida.matricula)) problemas.push('A matrícula deve ter só números.');
  if (saida.cpf && saida.cpf.replace(/\D/g, '').length !== 11) problemas.push('O CPF deve ter 11 dígitos.');
}
saida.erro = problemas.join(' ');

// Só segue o que o modo usa: no reuso a assinatura e os dados digitados são descartados.
const binary = { certificado: arquivos.certificado };
if (modo === 'primeiro_uso') binary.assinatura = arquivos.assinatura;
else binary.declaracao_base = arquivos.declaracao_base;
return [{ json: saida, binary }];

// Entrada da API de avaliação (POST multipart: certificado, versao, curso, matriz, nome, matricula).
// Só classifica: não gera declaração nem PDF final.
const fs = require('fs');
const cursos = JSON.parse(fs.readFileSync('/data/regras/cursos.json', 'utf8'));
const item = $input.first();
const corpo = item.json.body ?? {};
const certificado = item.binary?.certificado;

const versao = String(corpo.versao ?? 'v2').trim();
const cursoId = String(corpo.curso ?? 'eng-computacao').trim();
const curso = Object.hasOwn(cursos, cursoId) ? cursos[cursoId] : undefined;
const matriz = String(corpo.matriz ?? curso?.matriz_padrao ?? '').trim();
let erro = '';
if (!curso) erro = `Curso inválido. Use um destes: ${Object.keys(cursos).join(', ')}.`;
else if (!curso.matrizes[matriz]) erro = `Informe "matriz": ${Object.keys(curso.matrizes).join(', ')}.`;
else if (!certificado) erro = 'Envie o PDF no campo "certificado".';
else if (certificado.mimeType !== 'application/pdf') erro = 'O certificado precisa estar em PDF.';
else if (!/^v\d+$/.test(versao)) erro = 'O campo "versao" deve ter o formato v1, v2...';

return [{
  json: {
    origem: 'api',
    modo: 'api',
    versao,
    curso: cursoId,
    matriz,
    nome: String(corpo.nome ?? '').trim(),
    matricula: String(corpo.matricula ?? '').trim(),
    rg: '',
    cpf: '',
    erro,
  },
  binary: certificado ? { certificado } : {},
}];

// Recupera a entrada do formulário e substitui a foto pelo PNG recortado localmente.
const item = $('Normalizar formulário').first();
const resposta = $input.first().json;
if (resposta.statusCode !== 200 || !resposta.body?.imagem_base64) {
  return [{ json: { ...item.json, erro: resposta.body?.erro ?? 'Não consegui recortar a assinatura. Envie uma foto nítida em papel branco.' } }];
}
const assinatura = await this.helpers.prepareBinaryData(
  Buffer.from(resposta.body.imagem_base64, 'base64'), 'assinatura.png', 'image/png',
);
return [{ json: item.json, binary: { ...item.binary, assinatura } }];

// 1º uso: preenche o modelo oficial de declaração do curso (templates/, indicado em
// regras/cursos.json) com os dados e a assinatura, para o Gotenberg converter.
const fs = require('fs');
const item = $input.first();
const curso = JSON.parse(fs.readFileSync('/data/regras/cursos.json', 'utf8'))[item.json.curso];

// Chaves também: um nome com "{{assinatura}}" seria trocado pelos marcadores do modelo abaixo.
const escapar = (s) => String(s).replace(/[&<>"'{}]/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;', '{': '&#123;', '}': '&#125;' }[c]
));
const MIME = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png' };

const assinatura = item.binary.assinatura;
const bytes = await this.helpers.getBinaryDataBuffer(0, 'assinatura');
let html = fs.readFileSync(`/data/templates/${curso.modelo_declaracao}`, 'utf8');
for (const campo of ['nome', 'matricula', 'rg', 'cpf']) {
  html = html.replaceAll(`{{${campo}}}`, escapar(item.json[campo]));
}
html = html.replace('{{assinatura}}', `data:${assinatura.mimeType};base64,${bytes.toString('base64')}`);
// Imagens do próprio modelo (logo, brasão), lidas de templates/.
html = html.replace(/\{\{arquivo:([\w.-]+)\}\}/g, (_, nome) => (
  `data:${MIME[nome.split('.').pop()]};base64,${fs.readFileSync(`/data/templates/${nome}`).toString('base64')}`
));

const pagina = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
// A marca nos metadados diz ao serviço `declaracao` onde carimbar a data no reuso.
return [{ json: { ...item.json, marca_kit: curso.marca_kit }, binary: { ...item.binary, html: pagina } }];

// Guarda a declaração-base (sem data) gerada pelo Gotenberg: ela vai para o carimbo de data
// e também volta para o aluno baixar e reutilizar.
const item = $input.first();
const pdf = item.binary?.declaracao_base;
if (!pdf) {
  throw new Error(`Gotenberg não gerou a declaração: ${item.json.error?.message ?? 'sem resposta'}`);
}
const bytes = await this.helpers.getBinaryDataBuffer(0, 'declaracao_base');
const dados = $('Normalizar formulário').first().json;
return [{
  json: { ...dados, declaracao_base_b64: bytes.toString('base64') },
  binary: { declaracao_base: { ...pdf, fileName: 'minha-declaracao-base.pdf' } },
}];

// Junta o que a classificação precisa: o certificado, os dados para anonimizar e,
// no formulário, a declaração já datada pelo serviço `declaracao`.
const doFormulario = $('Normalizar formulário').isExecuted;
const normal = doFormulario ? $('Normalizar formulário').first() : $('Normalizar API').first();
const n = normal.json;

const saida = {
  origem: n.origem,
  modo: n.modo,
  versao: n.versao,
  curso: n.curso,
  matriz: n.matriz,
  dados_anonimizar: { nome: n.nome, matricula: n.matricula, rg: n.rg, cpf: n.cpf },
  declaracao_datada_b64: null,
  linha_data: null,
  erro: '',
};

if (doFormulario) {
  const r = $input.first().json; // resposta de /redatar (fullResponse)
  if (r.statusCode !== 200) {
    saida.erro = r.body?.erro ?? 'Não consegui colocar a data de hoje na declaração. Tente de novo.';
  } else {
    saida.declaracao_datada_b64 = r.body.pdf_base64;
    saida.linha_data = r.body.linha_data;
    if (n.modo === 'reuso') {
      // No reuso os dados vêm da própria declaração-base.
      saida.dados_anonimizar = { nome: r.body.nome, matricula: r.body.matricula, rg: r.body.rg, cpf: r.body.cpf };
    }
  }
}

return [{ json: saida, binary: { certificado: normal.binary.certificado } }];

// Troca nome, matrícula, RG, CPF e outros identificadores por marcas antes de o texto sair do Docker.
// O plano gratuito do Gemini pode usar o conteúdo enviado para treinar modelos.
const prep = $('Preparar certificado').first().json;
const resposta = $input.first().json; // resposta de /texto (fullResponse)

const MARCA = '[ALUNO]';
const PARTICULAS = new Set(['de', 'da', 'do', 'das', 'dos', 'e']);
const VARIANTES = {
  a: 'aáàâãä', e: 'eéèêë', i: 'iíìîï', o: 'oóòôõö', u: 'uúùûü', c: 'cç', n: 'nñ',
};
// O OCR confunde dígitos com letras parecidas (CPF "l23.456.789-O9").
const PARECIDOS = { 0: '0Oo', 1: '1lIi|', 2: '2Zz', 5: '5Ss', 6: '6b', 8: '8B' };
const D = '[\\dOoIl|]'; // dígito, ou letra que o OCR troca por dígito
// Depois destas expressões vem o nome de quem recebe o certificado.
const ANCORAS = 'certificamos que|certifica que|declaramos que|declara que|atestamos que|conferido a|conferida a|concedido a|concedida a|outorgado a';
const DEPOIS_DO_NOME = 'participou|concluiu|conclu[íi]da|apresentou|organizou|atuou|realizou|cursou|esteve|obteve|foi|portador|inscrit|CPF|RG|matr[íi]cula|aluno|aluna|estudante|discente';

const semAcento = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const escaparRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// "José" casa com "JOSE", "jose", "José"...
function padraoPalavra(palavra) {
  return [...semAcento(palavra)].map((ch) => (VARIANTES[ch] ? `[${VARIANTES[ch]}]` : escaparRegex(ch))).join('');
}

// "123.456" casa com "123456", "123 456", "123-456" e com as trocas do OCR ("l23.456").
function padraoDigitos(valor) {
  const digitos = String(valor ?? '').replace(/\D/g, '');
  if (digitos.length < 5) return null;
  return digitos.split('').map((d) => (PARECIDOS[d] ? `[${escaparRegex(PARECIDOS[d])}]` : d)).join('[\\s.\\-/]?');
}

// Distância de edição até 1 (um erro de OCR por palavra: "Marla" ~ "Maria").
function quase(a, b) {
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0;
  let j = 0;
  let diferencas = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) { i += 1; j += 1; continue; }
    diferencas += 1;
    if (diferencas > 1) return false;
    if (a.length > b.length) i += 1;
    else if (b.length > a.length) j += 1;
    else { i += 1; j += 1; }
  }
  return diferencas + (a.length - i) + (b.length - j) <= 1;
}

// Palavras do nome em qualquer ordem, completas ou com um erro de OCR, desde que apareçam pelo
// menos duas perto uma da outra ("SILVA, Maria", "Maria José", "Marla Silva"). Uma palavra sozinha
// fica: um sobrenome solto costuma ser nome de instituição ("Escola Silva").
function trocarPartesDoNome(t, palavras) {
  const nomes = palavras.map(semAcento).filter((p) => p.length >= 3 && !PARTICULAS.has(p));
  if (!nomes.length) return t;
  const ehNome = (w) => {
    const x = semAcento(w);
    return x.length >= 3 && nomes.some((n) => x === n || (n.length >= 5 && quase(x, n)));
  };
  const pedacos = t.split(/([\p{L}]+)/u); // palavras nas posições ímpares
  const posicoes = [];
  for (let i = 1; i < pedacos.length; i += 2) if (ehNome(pedacos[i])) posicoes.push(i);
  const perto = (a, b) => Math.abs(a - b) <= 6; // até 3 palavras de distância
  for (const i of posicoes) {
    if (posicoes.some((j) => j !== i && perto(i, j))) pedacos[i] = MARCA;
  }
  return pedacos.join('');
}

function anonimizar(texto, dados) {
  // "Fer-\nreira": a hifenização no fim da linha separaria o nome em duas palavras.
  let t = texto.replace(/(\p{L})-\s*\n\s*(\p{L})/gu, '$1$2');
  const trocar = (padrao, marca = MARCA) => {
    t = t.replace(new RegExp(padrao, 'giu'), marca);
  };

  const palavras = String(dados.nome ?? '').trim().split(/\s+/).filter(Boolean);
  if (palavras.length) {
    trocar(`(?<![\\p{L}])${palavras.map(padraoPalavra).join('\\s+')}(?![\\p{L}])`);
    t = trocarPartesDoNome(t, palavras);
  }
  // O nome logo depois de "Certificamos que", mesmo quando não bate com o informado.
  t = t.replace(new RegExp(`(${ANCORAS})\\s+(?!\\[ALUNO\\])([^,\\n]{3,80}?)(?=\\s*,|\\s+(?:${DEPOIS_DO_NOME})\\b)`, 'giu'),
    (_, ancora) => `${ancora} ${MARCA}`);

  for (const valor of [dados.matricula, dados.rg, dados.cpf]) {
    const padrao = padraoDigitos(valor);
    if (padrao) trocar(padrao);
  }
  if (dados.rg) trocar(escaparRegex(String(dados.rg)));
  // Padrões genéricos, para o que não veio nos dados (CPF de outra pessoa, matrícula etc.).
  trocar(`(?<![\\w])${D}{3}\\.${D}{3}\\.${D}{3}-${D}{2}(?![\\w])`);
  trocar('\\b\\d{3}\\.?\\d{3}\\.?\\d{3}-?\\d{2}\\b');
  trocar('\\b\\d{9,}\\b');
  trocar('[\\w.+-]+@[\\w-]+\\.[\\w.]+');
  // Links e códigos de verificação permitiriam achar o certificado (e o aluno) no site do emissor.
  trocar('(?:https?:\\/\\/|www\\.)\\S+', '[LINK]');
  trocar('\\b(?=[A-Za-z0-9-]*\\d)(?=[A-Za-z0-9-]*[A-Za-z])[A-Za-z0-9]{4,}(?:-[A-Za-z0-9]{3,}){1,}\\b', '[CODIGO]');
  trocar('\\b(?=[A-Za-z0-9]*\\d)(?=[A-Za-z0-9]*[A-Za-z])[A-Za-z0-9]{12,}\\b', '[CODIGO]');
  trocar('\\(?\\b\\d{2}\\)?\\s?9?\\d{4}-\\d{4}\\b', '[TELEFONE]');
  trocar('\\b\\d{5}-\\d{3}\\b', '[CEP]');
  return t.replace(/(\[ALUNO\][\s,]*){2,}/g, `${MARCA} `);
}

if (resposta.statusCode !== 200) {
  return [{ json: { ...prep, erro: resposta.body?.erro ?? 'Não consegui ler o certificado.' } }];
}
// No reuso o nome vem da declaração-base; sem ele, o nome do aluno iria ao Gemini sem máscara.
if (prep.origem === 'formulario' && !String(prep.dados_anonimizar?.nome ?? '').trim()) {
  return [{ json: { ...prep, erro: 'Não consegui ler o seu nome na declaração-base. Use a opção "Primeira vez" para gerar uma declaração nova.' } }];
}
const texto = resposta.body.texto ?? '';
if (texto.replace(/\s/g, '').length < 40) {
  return [{ json: { ...prep, erro: 'Não consegui ler o certificado, nem como imagem. Envie um PDF mais nítido: de preferência o arquivo original do emissor, ou uma digitalização reta e bem iluminada.' } }];
}
return [{ json: { ...prep, texto_anonimizado: anonimizar(texto, prep.dados_anonimizar), dados_anonimizar: undefined } }];

// Monta a chamada ao Gemini lendo o prompt e o schema versionados em prompts/.
const fs = require('fs');
const j = $input.first().json;

if (!/^v\d+$/.test(j.versao)) throw new Error(`Versão de prompt inválida: ${j.versao}`);
const arquivo = `/data/prompts/classificacao/${j.versao}.md`;
if (!fs.existsSync(arquivo)) throw new Error(`Prompt ${j.versao} não existe em prompts/classificacao/`);

const prompt = fs.readFileSync(arquivo, 'utf8');
const schema = JSON.parse(fs.readFileSync('/data/prompts/classificacao/schema.json', 'utf8'));
const curso = JSON.parse(fs.readFileSync('/data/regras/cursos.json', 'utf8'))[j.curso];
const tiposSigaa = JSON.parse(fs.readFileSync('/data/regras/tipos-sigaa.json', 'utf8'));

// "Na área" depende do curso, e cada colegiado tem categorias próprias: o modelo precisa saber qual é.
const base = JSON.parse(fs.readFileSync('/data/regras/base-cgrad-05-23.json', 'utf8')).categorias.map((c) => c.tipo_sigaa);
const extras = curso.categorias.map((c) => c.tipo_sigaa).filter((t) => !base.includes(t));

// Informações da matriz e código do SIGAA para o usuário específico
const matrizInfo = curso.matrizes[j.matriz];
const codigoMatriz = matrizInfo ? matrizInfo.codigo_sigaa : '';
const opcoesMatriz = codigoMatriz ? (tiposSigaa.matrizes[codigoMatriz] ?? []) : [];
const tiposDisponiveis = [...new Set(opcoesMatriz.map((o) => o.categoria).filter(Boolean))];

let situacaoAluno;
if (j.matriz === 'desde-2023-1') {
  situacaoAluno = 'Ingresso a partir de 2023.1 diretamente na grade nova';
} else if (j.matriz === 'migracao') {
  situacaoAluno = 'Ingresso anterior a 2023.1 que MIGROU para a grade nova (matriz de transição)';
} else {
  situacaoAluno = 'Ingresso até 2022.2 na grade antiga e NÃO migrou';
}

// O certificado não pode fechar a tag e "sair" da área de dados.
const certificado = (j.texto_anonimizado ?? '').replace(/<\/?\s*(certificado|curso|usuario)\s*>/gi, '');
const mensagem = [
  `<curso>${curso.nome}. Área de concentração: ${curso.area_concentracao}.`,
  `Categorias próprias deste curso: ${extras.length ? extras.join('; ') : 'nenhuma'}.</curso>`,
  `<usuario>`,
  `Curso: ${curso.nome}`,
  `Grade/Matriz: ${matrizInfo ? matrizInfo.rotulo : j.matriz} (${situacaoAluno})`,
  `Código do SIGAA deste aluno: ${codigoMatriz}`,
  `Tipos cadastrados no SIGAA para este código (${codigoMatriz}): ${tiposDisponiveis.length ? tiposDisponiveis.join('; ') : 'conferir catálogo'}.`,
  `</usuario>`,
  `<certificado>\n${certificado}\n</certificado>`,
].join('\n');

return [{
  json: {
    ...j,
    modelo: $env.GEMINI_MODEL || 'gemini-3.5-flash-lite',
    simular: !$env.GEMINI_API_KEY,
    requisicao: {
      systemInstruction: { parts: [{ text: prompt }] },
      contents: [{ role: 'user', parts: [{ text: mensagem }] }],
      generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: schema },
    },
  },
}];

// Sem GEMINI_API_KEY: devolve uma classificação de demonstração por palavras-chave, no mesmo
// formato da resposta do Gemini, para testar o resto do fluxo. A página avisa que é simulação.
const fs = require('fs');
const item = $input.first().json;
const texto = item.texto_anonimizado ?? '';
const t = texto.toLowerCase();
const horas = Number((t.match(/(\d+(?:[.,]\d+)?)\s*h(?:oras)?\b/) ?? [])[1]?.replace(',', '.')) || null;

let tipo = 'Curso extracurricular na área de concentração do curso';
if (/palestra|webinar/.test(t)) tipo = 'Palestra na área de concentração do curso';
else if (/ingl[eê]s|espanhol|idioma|english/.test(t)) tipo = 'Curso de Línguas Estrangeiras';

let codigoSigaa = 'ECL2023';
try {
  const cursos = JSON.parse(fs.readFileSync('/data/regras/cursos.json', 'utf8'));
